#!/usr/bin/env bash
# Tier 1 (Python always; Rust when `cargo` is on PATH, VBM_JSON_REQUIRE_CARGO=1 makes its absence a failure): the ABI description and the generated language bindings.
#   1. abi/vbm_json.abi.json agrees with include/vbm_json.h and LeanJson/Tape.lean (scripts/check_abi.py).
#   2. The committed bindings equal what scripts/gen-bindings.sh regenerates (drift check).
#   3. libvbm_json.so is built (scripts/build_shared.sh); the shared vectors (vbm-json-vectors-1, JSONTestSuite included, generated by the Lean REFERENCE) run through the Python binding
#      (tests/bindings/test_python.py) and the Rust binding (bindings/rust/tests/vectors.rs): verdict, error code, and the value read back to the reference's canonical bytes, every row.
#   4. NEGATIVE self-tests: a corrupted expected verdict, code and canonical form each fail each binding's test; mutants of each generated tape reader each fail it.
# Why Rust may be absent: cargo is not pinned by mise.toml and Tier 1 must not depend on a toolchain we do not install.
# Run: mise exec -- scripts/test_bindings.sh
set -euo pipefail
cd "$(dirname "$0")/.."
. .land/tool/lib/ran.sh   # ran_case / ran_done / must_fail: the self-tests count what they executed and a refused tool is a failure (.land/tool/docs/ran-evidence.md)
tmp=$(mktemp -d); trap 'rm -rf "$tmp"' EXIT

# 1. the description and the header
python3 scripts/check_abi.py; ran_case

# 2. the drift check
scripts/gen-bindings.sh --check; ran_case

# 3. the library and the vectors
scripts/build_shared.sh "$tmp/lib" >/dev/null
[ -x .lake/build/bin/vbm-json-vectors ] && [ -f .lake/build/lib/libvbm_x2djson_LeanJson.a ] || lake build vbm-json-vectors >/dev/null   # tier1 builds these once; concurrent lake runs in one tree are avoided
v=${VBM_JSON_VECTORS:-}   # tier1 generates the vectors once and shares them; alone, the script generates its own
[ -n "$v" ] || { .lake/build/bin/vbm-json-vectors --n 4 --out "$tmp/v" >/dev/null; v="$tmp/v/vectors.jsonl"; }
export VBM_JSON_LIB="$tmp/lib/libvbm_json.so"
py() { python3 tests/bindings/test_python.py "$1" "${2:-bindings/python}"; }
py "$v"; ran_case
# 4. Rust
if ! command -v cargo >/dev/null 2>&1; then
  if [ -n "${VBM_JSON_REQUIRE_CARGO:-}" ]; then echo "test_bindings: cargo is required here (VBM_JSON_REQUIRE_CARGO=1) and was not found" >&2; exit 1; fi
  echo "test_bindings: rust SKIPPED: cargo was not found on PATH (set VBM_JSON_REQUIRE_CARGO=1 to require it)"; ran_done test_bindings; exit 0
fi
export CARGO_TARGET_DIR="$tmp/target" CARGO_BUILD_JOBS=2 VBM_JSON_LIB_DIR="$tmp/lib"
rs() { VBM_JSON_VECTORS="$1" cargo test --quiet --offline --manifest-path "${2:-bindings/rust}/Cargo.toml" -- --nocapture; }
rs "$v" 2>&1 | grep -E '^vectors: ' || { echo "test_bindings: the rust vectors test did not report" >&2; exit 1; }; ran_case
ran_done test_bindings
echo "test_bindings: ok"
